import React, { useState } from "react";
import { Link, useNavigate } from 'react-router-dom';

function PaymentMethod() {
    const [account, setAccount] = useState('')
    const [fullName, setFullName] = useState('')
    const [expirationDate, setExpirationDate] = useState('')
    const [cvvCode, setCvvCode] = useState('')
    const navigate = useNavigate()

    async function AddPaymentMethod(event) {
        event.preventDefault()

        const userData = {
            "renterId": localStorage.renterId,
            account,
            fullName,
            expirationDate,
            cvvCode
        };

        if (!account || !fullName || !expirationDate || !cvvCode) {
            alert('Пожалуйста заполните все поля');
            return;
        } else {
            try {
                const response = await fetch(`http://localhost:8083/user-account`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(userData),
                });
                const data = await response.json()

                if (data) {
                    alert('Операция Успешна')
                    navigate('/Home')
                }
            } catch (error) {
                console.error('Error fetching payment details:', error);
            }

        }
    }

    return (
        <div className="Subscription">
            <h1>Детали оплаты</h1>
            <h3>Осталось совсем немного. Всего лишь некоторые платежные реквизиты, и вы сможете сделать свой первый заказ уже сегодня. (Первая доставка бесплатно!)</h3>
            <div className="line"></div>

        </div>
    )
}

export default PaymentMethod;
